arguments.rule_content:
{
  "title": "Detect QR Code Phishing Emails (Quishing)",
  "id": "e5b6c7d8-9f10-11ea-bb37-0242ac130002",
  "description": "Detect emails containing PDF attachments with embedded QR codes linking to external credential harvesting domains.",
  "status": "stable",
  "author": "SOC Team",
  "date": "2026-04-09",
  "logsource": {
    "product": "email",
    "service": "gateway"
  },
  "detection": {
    "selection": {
      "attachment_extension": "pdf",
      "attachment_content": "QR Code",
      "subject|contains": ["MFA Enrollment Required", "Scan QR Code"]
    },
    "condition": "selection"
  },
  "fields": ["sender", "recipient", "subject", "attachment_name", "attachment_hash", "url"],
  "falsepositives": ["Legitimate MFA enrollment communications"],
  "level": "high"
}
